        let p2 = x[5] * x[8];
        let p3 = x[9] * x[9];
        let p4 = x[0] * x[0];
        let p5 = x[1] * x[1];
        let p6 = x[2] * x[2];
        let p7 = x[3] * x[7];
        let p8 = x[3] * x[8];
        let p9 = x[4] * x[6];
        let p10 = x[4] * x[8];
        let p11 = x[5] * x[6];
        let p12 = x[5] * x[7];
        let p13 = x[0] * x[1];
        let p14 = x[0] * x[2];
        let p15 = x[0] * x[9];
        let p16 = x[1] * x[2];
        let p17 = x[1] * x[9];
        let p18 = x[2] * x[9];
        let p19 = p0 * p4;
        let p20 = p3 * p4;
        let p21 = p7 * p13;
        let p22 = p9 * p13;
        let p23 = p8 * p14;
        let p24 = p11 * p14;
        let p25 = p10 * p15;
        let p26 = p12 * p15;
        let p27 = p1 * p5;
        let p28 = p3 * p5;
        let p29 = p10 * p16;
        let p30 = p12 * p16;
        let p31 = p8 * p17;
        let p32 = p11 * p17;
        let p33 = p2 * p6;
        let p34 = p3 * p6;
        let p35 = p7 * p18;
        let p36 = p9 * p18;
        let p37 = p7 * p7;
        let p38 = p8 * p8;
        let p39 = p0 * p1;
        let p40 = p0 * p2;
        let p41 = p9 * p9;
        let p42 = p10 * p10;
        let p43 = p1 * p2;
        let p44 = p11 * p11;
        let p45 = p12 * p12;
        let p46 = p3 - p4;
        let p47 = p5 + p6;
        let p48 = p46 - p47;
        let p49 = p0 + p1;
        let p50 = p2 + p49;
        let p51 = p50 * T::from_i64(2);
        let p52 = p48 + p51;
        let p53 = p20 + p28;
        let p54 = p34 + p53;
        let p55 = p37 + p38;
        let p56 = p54 + p55;
        let p57 = p41 + p42;
