impl<T: gx::Real> Quadvector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[4];
        let t4 = t0 + t1;
        let t5 = t2 + t4;
        let t6 = t3 * T::from_i64(2);
        let t7 = t5 + t6;
        let t8 = -t7;
        t8
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (26 mul, 12 add, 1 div).
    #[inline]
    pub fn inverse(self) -> Quadvector<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[4];
        let t4 = t0 * t0;
        let t5 = t0 * t1;
        let t6 = t0 * t2;
        let t7 = t0 * t3;
        let t8 = t1 * t1;
        let t9 = t1 * t2;
        let t10 = t1 * t3;
        let t11 = t2 * t2;
        let t12 = t2 * t3;
        let t13 = t3 * t3;
        let t14 = t4 + t8;
        let t15 = t11 + t14;
        let t16 = t5 + t6;
        let t17 = t9 + t16;
        let t18 = t17 * T::from_i64(2);
        let t19 = t7 + t10;
        let t20 = t12 + t13;
        let t21 = t19 + t20;
        let t22 = t21 * T::from_i64(4);
        let t23 = t15 + t18;
        let t24 = t22 + t23;
        let t25 = t24.recip();
        let t26 = t0 * t25;
        let t27 = t1 * t25;
        let t28 = t2 * t25;
        let t29 = t3 * t25;
        let t30 = t26 + t27;
        let t31 = t28 + t30;
        let t32 = t29 * T::from_i64(2);
        let t33 = t31 + t32;
        let t34 = x[0] * t33;
        let t35 = x[1] * t33;
        let t36 = x[2] * t33;
        let t37 = x[3] * t33;
        let t38 = x[4] * t33;
        let t39 = -t34;
        let t40 = -t35;
        let t41 = -t36;
        let t42 = -t37;
        let t43 = -t38;
        Quadvector::from_coeffs([t39, t40, t41, t42, t43])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let p1 = x[1] * x[1];
        let p2 = x[2] * x[2];
        let p3 = x[3] * x[4];
        let p4 = p0 + p1;
        let p5 = p2 + p4;
        let p6 = p3 * T::from_i64(2);
        let p7 = p5 + p6;
        let p8 = -p7;
        let s0 = (p8).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        let t4 = x[4] * s0;
        gx::Unit::new_unchecked(Quadvector::from_coeffs([t0, t1, t2, t3, t4]))
    }

}

