impl<T: gx::Real> Motor<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[3];
        let t4 = t0 + t1;
        let t5 = t2 + t3;
        let t6 = t4 + t5;
        t6
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (55 mul, 28 add, 1 div).
    #[inline]
    pub fn inverse(self) -> Motor<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[3];
        let t4 = t0 * t0;
        let t5 = t0 * t1;
        let t6 = t0 * t2;
        let t7 = t0 * t3;
        let t8 = t1 * t1;
        let t9 = t1 * t2;
        let t10 = t1 * t3;
        let t11 = t2 * t2;
        let t12 = t2 * t3;
        let t13 = t3 * t3;
        let t14 = t4 + t8;
        let t15 = t11 + t13;
        let t16 = t14 + t15;
        let t17 = t5 + t6;
        let t18 = t7 + t17;
        let t19 = t9 + t10;
        let t20 = t12 + t19;
        let t21 = t18 + t20;
        let t22 = t21 * T::from_i64(2);
        let t23 = t16 + t22;
        let t24 = t23.recip();
        let t25 = t0 * t24;
        let t26 = t1 * t24;
        let t27 = t2 * t24;
        let t28 = t3 * t24;
        let t29 = t25 + t26;
        let t30 = t27 + t28;
        let t31 = t29 + t30;
        let t32 = t25 - t26;
        let t33 = x[0] * x[7];
        let t34 = t24 * t33;
        let t35 = x[1] * x[4];
        let t36 = t24 * t35;
        let t37 = t34 - t36;
        let t38 = t27 - t28;
        let t39 = x[2] * x[5];
        let t40 = t24 * t39;
        let t41 = x[3] * x[6];
        let t42 = t24 * t41;
        let t43 = t40 + t42;
        let t44 = x[0] * x[1];
        let t45 = x[2] * x[3];
        let t46 = t24 * t44;
        let t47 = t24 * t45;
        let t48 = x[0] * t31;
        let t49 = x[1] * t31;
        let t50 = x[2] * t31;
        let t51 = x[3] * t31;
        let t52 = x[7] * t46;
        let t53 = x[1] * t43;
        let t54 = x[4] * t32;
        let t55 = x[4] * t30;
        let t56 = x[6] * t47;
        let t57 = x[2] * t37;
        let t58 = x[5] * t29;
        let t59 = x[5] * t38;
        let t60 = x[5] * t47;
        let t61 = x[3] * t37;
        let t62 = x[6] * t29;
        let t63 = x[6] * t38;
        let t64 = x[4] * t46;
        let t65 = x[0] * t43;
        let t66 = x[7] * t32;
        let t67 = x[7] * t30;
        let t68 = -t49;
        let t69 = -t50;
        let t70 = -t51;
        let t71 = t54 + t55;
        let t72 = t53 - t52;
        let t73 = t72 * T::from_i64(2);
        let t74 = t73 - t71;
        let t75 = t59 - t58;
        let t76 = t56 - t57;
        let t77 = t76 * T::from_i64(2);
        let t78 = t75 + t77;
        let t79 = t62 + t63;
        let t80 = t60 - t61;
        let t81 = t80 * T::from_i64(2);
        let t82 = t81 - t79;
        let t83 = t67 - t66;
        let t84 = t64 + t65;
        let t85 = t84 * T::from_i64(2);
        let t86 = t83 + t85;
        Motor::from_coeffs([t48, t68, t69, t70, t74, t78, t82, t86])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let p1 = x[1] * x[1];
        let p2 = x[2] * x[2];
        let p3 = x[3] * x[3];
        let p4 = x[0] * x[7];
        let p5 = x[1] * x[4];
        let p6 = x[2] * x[5];
        let p7 = x[3] * x[6];
        let p8 = p0 + p1;
        let p9 = p2 + p3;
        let p10 = p8 + p9;
        let p11 = p4 - p5;
        let p12 = p6 + p7;
        let p13 = p11 - p12;
        let p14 = p13 * T::from_i64(2);
        let [s0, s1] = gx::study::rsqrt_nil(p10, p14);
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        let t4 = x[1] * s1;
        let t5 = x[4] * s0;
        let t6 = x[2] * s1;
        let t7 = x[5] * s0;
        let t8 = x[3] * s1;
        let t9 = x[6] * s0;
        let t10 = x[0] * s1;
        let t11 = x[7] * s0;
        let t12 = t5 - t4;
        let t13 = t7 - t6;
        let t14 = t9 - t8;
        let t15 = t10 + t11;
        gx::Unit::new_unchecked(Motor::from_coeffs([t0, t1, t2, t3, t12, t13, t14, t15]))
    }

    /// The principal square root of a unit versor, `normalize(1 + R)` (not defined for `R = -1`).
    #[inline]
    pub fn sqrt(self) -> gx::Unit<Self> {
        let mut c = self.c;
        c[0] = c[0] + T::one();
        Motor::from_coeffs(c).normalized()
    }

}

impl<T: gx::Real> gx::Log<Twist<(), T>> for gx::Unit<Motor<(), T>> {
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(self) -> Twist<(), T> {
        let x = self.into_inner().c;
        let p0 = x[1] * x[1];
        let p1 = x[2] * x[2];
        let p2 = x[3] * x[3];
        let p3 = x[1] * x[4];
        let p4 = x[2] * x[5];
        let p5 = x[3] * x[6];
        let p6 = p0 + p1;
        let p7 = p2 + p6;
        let p8 = -p7;
        let p9 = p3 + p4;
        let p10 = p5 + p9;
        let p11 = p10 * T::from_i64(2);
        let [h0, h1] = gx::study::log_coeffs_rotation((x[0], x[7]), (p8, p11));
        let t0 = x[1] * h0;
        let t1 = x[2] * h0;
        let t2 = x[3] * h0;
        let t3 = x[1] * h1;
        let t4 = x[4] * h0;
        let t5 = x[2] * h1;
        let t6 = x[5] * h0;
        let t7 = x[3] * h1;
        let t8 = x[6] * h0;
        let t9 = t4 - t3;
        let t10 = t6 - t5;
        let t11 = t8 - t7;
        Twist::from_coeffs([t0, t1, t2, t9, t10, t11])
    }
}

#[doc = "The even subalgebra: all conformal versors of even grade (rotors, translators, dilators, transversions)."]
///
/// Blades, in coefficient order: `[1, e23, e31, e12, e1o, e2o, e3o, e1i, e2i, e3i, eoi, e23oi, e31oi, e12oi, e123o, e123i]`.
///
/// `S` lists the open slots: `Even` (that is, `Even<()>`) is a value, `Even<(A,)>` a
/// linear map from `A`, `Even<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Even<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 16],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Even<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Even<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Even<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Even<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Even");
        for (b, c) in <Even as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Even {
    const N: usize = 16;
    const NAME: &'static str = "Even";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["1", "e23", "e31", "e12", "e1o", "e2o", "e3o", "e1i", "e2i", "e3i", "eoi", "e23oi", "e31oi", "e12oi", "e123o", "e123i"];
    type Arr<X: gx::Elem> = [X; 16];
    type Mv<S: gx::Slots, T: gx::Coef> = Even<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(f: impl FnMut(usize) -> X) -> [X; 16] {
        core::array::from_fn(f)
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 16], f: impl FnMut(&X) -> Y) -> [Y; 16] {
        a.each_ref().map(f)
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 16],
        b: &[Y; 16],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 16] {
        core::array::from_fn(|i| f(&a[i], &b[i]))
    }
}

