impl<S: gx::Slots, T: gx::Real> core::ops::Div<T> for Odd<S, T> {
    type Output = Self;
    #[inline(always)]
    fn div(self, rhs: T) -> Self {
        let r = rhs.recip();
        Odd { c: self.c.map(|x| gx::SlotArr::<S, T>(x).scale(r).0) }
    }
}

