impl<T: gx::Real> Multivector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[3];
        let t4 = x[4] * x[5];
        let t5 = x[6] * x[6];
        let t6 = x[7] * x[7];
        let t7 = x[8] * x[8];
        let t8 = x[9] * x[12];
        let t9 = x[10] * x[13];
        let t10 = x[11] * x[14];
        let t11 = x[15] * x[15];
        let t12 = x[16] * x[19];
        let t13 = x[17] * x[20];
        let t14 = x[18] * x[21];
        let t15 = x[22] * x[22];
        let t16 = x[23] * x[23];
        let t17 = x[24] * x[24];
        let t18 = x[25] * x[25];
        let t19 = x[26] * x[26];
        let t20 = x[27] * x[27];
        let t21 = x[28] * x[28];
        let t22 = x[29] * x[30];
        let t23 = x[31] * x[31];
        let t24 = t0 + t1;
        let t25 = t2 + t3;
        let t26 = t24 + t25;
        let t27 = t5 + t6;
        let t28 = t7 + t18;
        let t29 = t27 + t28;
        let t30 = t26 + t29;
        let t31 = t11 + t15;
        let t32 = t16 + t17;
        let t33 = t31 + t32;
        let t34 = t19 + t20;
        let t35 = t21 + t23;
        let t36 = t34 + t35;
        let t37 = t33 + t36;
        let t38 = t30 - t37;
        let t39 = t4 + t8;
        let t40 = t9 + t10;
        let t41 = t39 + t40;
        let t42 = t12 + t13;
        let t43 = t14 + t22;
        let t44 = t42 + t43;
        let t45 = t41 + t44;
        let t46 = t45 * T::from_i64(2);
        let t47 = t38 - t46;
        t47
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

}

